//! The host's design tokens, generated from `DESIGN.md`, for the widget kit and the host. No item
//! here is a host-surface token: those are in `host-surfaces`, which only the host may use
//! (specs/007-host-visual-design/research.md, R6).

// Generated by `cargo xtask design` and compared byte for byte, so rustfmt leaves it alone
#[rustfmt::skip]
mod generated;

pub use generated::{GrayFamily, Icon, Scale, elevation, radius, spacing, typography};

/// An opaque sRGB color.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Rgb {
    pub r: u8,
    pub g: u8,
    pub b: u8,
}

impl Rgb {
    const fn from(channels: [u8; 3]) -> Rgb {
        Rgb {
            r: channels[0],
            g: channels[1],
            b: channels[2],
        }
    }
}

fn linear(channel: u8) -> f64 {
    let value = f64::from(channel) / 255.0;
    if value <= 0.04045 {
        value / 12.92
    } else {
        ((value + 0.055) / 1.055).powf(2.4)
    }
}

/// WCAG 2.2 contrast ratio, from 1 to 21.
pub fn contrast(a: Rgb, b: Rgb) -> f64 {
    let luminance = |c: Rgb| 0.2126 * linear(c.r) + 0.7152 * linear(c.g) + 0.0722 * linear(c.b);
    let (la, lb) = (luminance(a), luminance(b));
    (la.max(lb) + 0.05) / (la.min(lb) + 0.05)
}

/// A theme the host draws in.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Theme {
    Light,
    Dark,
}

/// The theme the person picks: one of the two, or the system's.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum ThemePick {
    Light,
    Dark,
    System,
}

/// The host color: none (the gray family), or a chromatic scale.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum HostColor {
    Monochrome,
    Scale(Scale),
}

/// The corner radius the person picks (`DESIGN.md`, radius-picks).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Radius {
    None,
    Small,
    Medium,
    Large,
    Full,
}

impl Radius {
    pub const ALL: [Radius; 5] = [
        Radius::None,
        Radius::Small,
        Radius::Medium,
        Radius::Large,
        Radius::Full,
    ];

    /// The name `DESIGN.md` gives it.
    pub const fn name(self) -> &'static str {
        match self {
            Radius::None => "none",
            Radius::Small => "small",
            Radius::Medium => "medium",
            Radius::Large => "large",
            Radius::Full => "full",
        }
    }

    /// The radius in pixels.
    pub const fn px(self) -> f32 {
        match self {
            Radius::None => radius::NONE,
            Radius::Small => radius::SMALL,
            Radius::Medium => radius::MEDIUM,
            Radius::Large => radius::LARGE,
            Radius::Full => radius::FULL,
        }
    }
}

/// What a widget color came too close to.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Other {
    /// The host color.
    Host(Scale),
    /// A status scale: green, amber, red.
    Ok,
    Warning,
    Error,
}

/// Why an appearance is refused; the host words it when the picking screen exists.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Refusal {
    /// The widget color's hue is under the rule's distance from another color's; `degrees` is
    /// the distance, rounded down.
    TooClose {
        widget: Scale,
        other: Other,
        degrees: u16,
    },
    /// A scale with too little chroma to be told apart by its hue (FR-013).
    NotChromatic { scale: Scale },
}

/// The person's picks (FR-010).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Appearance {
    pub gray: GrayFamily,
    pub host: HostColor,
    pub widget: Scale,
    pub radius: Radius,
    pub theme: ThemePick,
}

impl Scale {
    fn index(self) -> usize {
        Scale::ALL
            .iter()
            .position(|scale| *scale == self)
            .expect("every scale is in ALL")
    }

    /// OKLCH hue of light step 9, in degrees.
    pub fn hue(self) -> f64 {
        generated::HUE[self.index()]
    }

    /// OKLCH chroma of light step 9.
    pub fn chroma(self) -> f64 {
        generated::CHROMA[self.index()]
    }

    /// Whether the scale has enough chroma to be a host or widget color (FR-013).
    pub fn is_chromatic(self) -> bool {
        self.chroma() >= generated::NEUTRAL_BELOW_CHROMA
    }
}

/// The shorter way round the hue circle, 0–180°.
fn hue_distance(a: f64, b: f64) -> f64 {
    let difference = (a - b).rem_euclid(360.0);
    difference.min(360.0 - difference)
}

impl Appearance {
    /// The neutral default: pure gray, a monochrome host, blue widgets, medium corners, the
    /// system's theme (FR-012).
    pub const DEFAULT: Appearance = Appearance {
        gray: generated::DEFAULT_GRAY,
        host: match generated::DEFAULT_HOST {
            None => HostColor::Monochrome,
            Some(scale) => HostColor::Scale(scale),
        },
        widget: generated::DEFAULT_WIDGET,
        radius: generated::DEFAULT_RADIUS,
        theme: generated::DEFAULT_THEME,
    };

    /// Accepts the picks, or says why not: a neutral host or widget color, or a widget color
    /// within the rule's distance of the host color or of a status scale (FR-011, FR-013).
    pub fn validate(&self) -> Result<(), Refusal> {
        if let HostColor::Scale(host) = self.host
            && !host.is_chromatic()
        {
            return Err(Refusal::NotChromatic { scale: host });
        }
        if !self.widget.is_chromatic() {
            return Err(Refusal::NotChromatic { scale: self.widget });
        }
        let [ok, warning, error] = generated::STATUS;
        let mut others = Vec::with_capacity(4);
        if let HostColor::Scale(host) = self.host {
            others.push((Other::Host(host), host));
        }
        others.extend([
            (Other::Ok, ok),
            (Other::Warning, warning),
            (Other::Error, error),
        ]);
        for (other, scale) in others {
            let distance = hue_distance(self.widget.hue(), scale.hue());
            if distance < generated::HUE_DISTANCE {
                return Err(Refusal::TooClose {
                    widget: self.widget,
                    other,
                    degrees: distance.floor() as u16,
                });
            }
        }
        Ok(())
    }
}

/// What the generated role tables of this crate and of `host-surfaces` are made of, and how a
/// role resolves. For generated code, not for widgets: a widget asks for a `Tone`.
#[doc(hidden)]
pub mod raw {
    use super::{Appearance, GrayFamily, HostColor, Rgb, Scale, Theme, generated};

    /// Which pick or fixed scale a role reads.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum Source {
        Gray,
        Widget,
        Host,
        Ok,
        Warning,
        Error,
        Overlay,
    }

    /// The step a role takes in one theme.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum StepRef {
        Radix(u8),
        White,
        Black,
        SolidText,
    }

    /// A color role: where it reads its color in each theme.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub struct RoleDef {
        pub name: &'static str,
        pub source: Source,
        pub light: StepRef,
        pub dark: StepRef,
    }

    fn gray_steps(gray: GrayFamily, theme: Theme) -> &'static [[u8; 3]; 12] {
        let index = GrayFamily::ALL
            .iter()
            .position(|g| *g == gray)
            .expect("in ALL");
        match theme {
            Theme::Light => &generated::GRAY_LIGHT[index],
            Theme::Dark => &generated::GRAY_DARK[index],
        }
    }

    fn scale_steps(scale: Scale, theme: Theme) -> &'static [[u8; 3]; 12] {
        let index = Scale::ALL.iter().position(|s| *s == scale).expect("in ALL");
        match theme {
            Theme::Light => &generated::SCALE_LIGHT[index],
            Theme::Dark => &generated::SCALE_DARK[index],
        }
    }

    /// A role's color under an appearance in a theme, with its opacity: 1 for every role but
    /// the overlay, which is black at a `blackA` step's opacity.
    pub fn resolve(role: &RoleDef, appearance: &Appearance, theme: Theme) -> (Rgb, f64) {
        let step = match theme {
            Theme::Light => role.light,
            Theme::Dark => role.dark,
        };
        let scale = match role.source {
            Source::Gray => None,
            Source::Widget => Some(appearance.widget),
            Source::Host => match appearance.host {
                HostColor::Monochrome => None,
                HostColor::Scale(scale) => Some(scale),
            },
            Source::Ok => Some(generated::STATUS[0]),
            Source::Warning => Some(generated::STATUS[1]),
            Source::Error => Some(generated::STATUS[2]),
            Source::Overlay => {
                let StepRef::Radix(n) = step else {
                    return (Rgb { r: 0, g: 0, b: 0 }, 1.0);
                };
                return (
                    Rgb { r: 0, g: 0, b: 0 },
                    generated::BLACK_A[usize::from(n) - 1],
                );
            }
        };
        let steps = scale.map_or_else(
            || gray_steps(appearance.gray, theme),
            |s| scale_steps(s, theme),
        );
        let dark_text = Rgb::from(gray_steps(appearance.gray, Theme::Light)[11]);
        let color = match step {
            StepRef::Radix(n) => Rgb::from(steps[usize::from(n) - 1]),
            StepRef::White => Rgb {
                r: 255,
                g: 255,
                b: 255,
            },
            StepRef::Black => Rgb { r: 0, g: 0, b: 0 },
            StepRef::SolidText => {
                let index = scale.and_then(|s| Scale::ALL.iter().position(|x| *x == s));
                match index.map(|i| generated::SOLID_TEXT[i]) {
                    Some(generated::SolidText::White) => Rgb {
                        r: 255,
                        g: 255,
                        b: 255,
                    },
                    _ => dark_text,
                }
            }
        };
        (color, 1.0)
    }

    /// A role of this crate's table, by name.
    pub(crate) fn role(name: &str) -> &'static RoleDef {
        generated::ROLES
            .iter()
            .find(|role| role.name == name)
            .expect("a role DESIGN.md defines")
    }
}

/// The five tones a widget can ask for; never a color (FR-015).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Tone {
    Default,
    Accent,
    Ok,
    Warning,
    Error,
}

/// A tone name the kit does not have: the kit draws `Tone::Default` and logs the name, escaped
/// (FR-017).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct UnknownTone(pub String);

impl Tone {
    pub const ALL: [Tone; 5] = [
        Tone::Default,
        Tone::Accent,
        Tone::Ok,
        Tone::Warning,
        Tone::Error,
    ];

    /// The tone a widget names, exactly; anything else comes back as `UnknownTone`.
    pub fn parse(name: &str) -> Result<Tone, UnknownTone> {
        Ok(match name {
            "default" => Tone::Default,
            "accent" => Tone::Accent,
            "ok" => Tone::Ok,
            "warning" => Tone::Warning,
            "error" => Tone::Error,
            _ => return Err(UnknownTone(name.to_owned())),
        })
    }
}

/// A tone's colors: its text on its surface, its border, and, for a status, the icon and the
/// color it is drawn in (FR-025).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ToneColors {
    pub text: Rgb,
    pub surface: Rgb,
    pub border: Option<Rgb>,
    pub icon: Option<(Icon, Rgb)>,
}

/// A role of this crate by its `DESIGN.md` name (`canvas`, `surface`, `divider`, `text`, ...),
/// resolved under an appearance in a theme; `None` for a name this crate does not hold, such as a
/// host surface. For the host, which draws its frames and chrome from these roles; widget content
/// asks for a [`Tone`] instead.
pub fn role_color(name: &str, appearance: &Appearance, theme: Theme) -> Option<Rgb> {
    generated::ROLES
        .iter()
        .find(|role| role.name == name)
        .map(|role| raw::resolve(role, appearance, theme).0)
}

/// A tone's colors under the person's appearance in a theme.
pub fn tone(tone: Tone, appearance: &Appearance, theme: Theme) -> ToneColors {
    let index = Tone::ALL.iter().position(|t| *t == tone).expect("in ALL");
    let definition = &generated::TONES[index];
    let color = |name: &str| raw::resolve(raw::role(name), appearance, theme).0;
    ToneColors {
        text: color(definition.text),
        surface: color(definition.surface),
        border: definition.border.map(color),
        icon: definition.status_icon.zip(definition.icon.map(color)),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn role_color_resolves_this_crates_roles_only() {
        let appearance = Appearance::DEFAULT;
        // DESIGN.md's front matter: canvas #f1f0ef in the light theme, sand by default
        assert_eq!(
            role_color("canvas", &appearance, Theme::Light),
            Some(Rgb {
                r: 0xf1,
                g: 0xf0,
                b: 0xef
            })
        );
        assert_eq!(role_color("host-strong", &appearance, Theme::Light), None);
        assert_eq!(role_color("nothing", &appearance, Theme::Light), None);
    }

    #[test]
    fn radius_names_are_design_mds_picks() {
        let names: Vec<&str> = Radius::ALL.iter().map(|radius| radius.name()).collect();
        assert_eq!(names, generated::RADIUS_PICKS);
    }
}
